import{_ as o,C as r,o as i,c,a2 as a,j as t,G as l}from"./chunks/framework.BgSoyxN5.js";const T=JSON.parse('{"title":"Экономическое здоровье США: вся макро-картина, раз в месяц | TickerForge","description":"Двадцать с лишним макро-индикаторов как один композит с четырьмя полосами. Публикуется ежемесячно, с разбором того, что держит счёт и что тянет его вниз.","frontmatter":{"title":"Экономическое здоровье США: вся макро-картина, раз в месяц | TickerForge","description":"Двадцать с лишним макро-индикаторов как один композит с четырьмя полосами. Публикуется ежемесячно, с разбором того, что держит счёт и что тянет его вниз.","aside":false,"locale":"ru","alternateLocales":{"en":"/market-intelligence/economic-health","ru":"/ru/market-intelligence/economic-health"},"pageClass":"partners-page"},"headers":[],"relativePath":"ru/market-intelligence/economic-health.md","filePath":"ru/market-intelligence/economic-health.md","lastUpdated":1788410450000}'),h={name:"ru/market-intelligence/economic-health.md"},p={class:"partners-wide"},m={class:"partners-post-gallery"};function d(_,e,g,u,k,f){const n=r("PartnerPostImage"),s=r("PartnerChannelCta");return i(),c("div",null,[e[0]||(e[0]=a('<h1 id="экономическое-здоровье-сша" tabindex="-1">Экономическое здоровье США <a class="header-anchor" href="#экономическое-здоровье-сша" aria-label="Permalink to &quot;Экономическое здоровье США&quot;">​</a></h1><p>Макро-новости приходят по одному индикатору за раз: день CPI, день пейроллов, день ISM. Сумму не публикует никто. Это чтение публикует — раз в месяц.</p><div class="partners-hero-actions"><a class="partners-button partners-button--primary" href="https://t.me/TickerForgeBot?start=src_channel_us_economy" rel="nofollow">Открыть меню «Экономика США»</a><a class="partners-button partners-button--secondary" href="#publish">Публиковать в своём канале</a></div><p class="partners-locale-switch"><a href="/market-intelligence/economic-health" hreflang="en">Read this page in English</a></p><p class="partners-backlink"><a href="/ru/market-intelligence/">Все чтения Market Intelligence</a> · <a href="/ru/market-intelligence/market-regime">Рыночный режим</a> · <a href="/ru/market-intelligence/market-stress">Рыночный стресс</a></p><h2 id="answers" tabindex="-1">На какой вопрос отвечает <a class="header-anchor" href="#answers" aria-label="Permalink to &quot;На какой вопрос отвечает {#answers}&quot;">​</a></h2><p><strong>«Макро-фон поддерживает принятие риска или работает против него?»</strong></p><p>Одна публикация на этот вопрос не отвечает. Пейроллы лучше ожиданий и CPI хуже в одном и том же месяце — обычное дело, и лента, осветившая оба, оставляет читателя с двумя фактами и без позиции. Композит существует потому, что ответ живёт в совокупности, а не в последнем релизе.</p><h2 id="why" tabindex="-1">Почему композит сильнее календаря публикаций <a class="header-anchor" href="#why" aria-label="Permalink to &quot;Почему композит сильнее календаря публикаций {#why}&quot;">​</a></h2><div class="partners-wide partners-wide--compact"><ul class="partners-feature-list"><li><strong>Двадцать с лишним индикаторов — один счёт.</strong> Каждый оценивается относительно собственной исторической нормы: «хорошо» означает хорошо по меркам этого ряда, а не относительно круглого числа.</li><li><strong>Четыре полосы, а не голая цифра.</strong> Риск рецессии, Замедление, Стабильный рост, Подъём. Счёт 61 сам по себе не значит ничего — значит полоса, в которую он попал.</li><li><strong>Драйверы названы с обеих сторон.</strong> В каждом посте перечислено, что держит счёт и что тянет его вниз. Это та часть, с которой можно спорить, и та, что превращает число из вердикта в аргумент.</li><li><strong>Предварительное названо предварительным.</strong> Поздние данные меняют счёт, и пост говорит, какая доля месяца отчиталась, а не выдаёт неполное чтение за окончательное.</li><li><strong>Вместе с ним идут последние три месяца.</strong> Одно макро-число — это мелочь. Направление трёх — уже сюжет.</li></ul></div><h2 id="example" tabindex="-1">Как выглядит пост <a class="header-anchor" href="#example" aria-label="Permalink to &quot;Как выглядит пост {#example}&quot;">​</a></h2>',11)),t("div",p,[t("div",m,[l(n,{src:"/partners/examples/economic-health-sample.png",alt:"Пост TickerForge «Экономическое здоровье США»: месячный макро-композит с полосой, драйверами с обеих сторон и последними тремя месяцами",caption:"Счёт, его полоса, что его сдвинуло и тренд за ним.","zoom-label":"Открыть пример поста в полном размере","close-label":"Закрыть","enlarge-label":"Нажмите, чтобы открыть в полном размере","shrink-label":"Нажмите, чтобы вписать в экран"})])]),e[1]||(e[1]=a('<h2 id="method" tabindex="-1">Как это считается <a class="header-anchor" href="#method" aria-label="Permalink to &quot;Как это считается {#method}&quot;">​</a></h2><p>Каждый индикатор превращается в z-оценку относительно собственной истории, знак нормализуется так, что «вверх» всегда значит «лучше для экономики» — включая ряды вроде безработицы, где плохо как раз более высокое опубликованное значение. Дальше — затухание по возрасту данных, веса и приведение к шкале 0–100.</p><p>Полное описание: <a href="/blog/economic-health-score">How we score the economy</a>.</p><h2 id="publish" tabindex="-1">Два способа этим пользоваться <a class="header-anchor" href="#publish" aria-label="Permalink to &quot;Два способа этим пользоваться {#publish}&quot;">​</a></h2><div class="partners-wide partners-wide--compact"><ul class="partners-feature-list"><li><strong>Читать.</strong> Месячный пост выходит в публичном канале TickerForge; все 20+ индикаторов, график счёта и месячные алерты — в меню «Экономика США» в боте.</li><li><strong>Публиковать.</strong> Одобренный партнёр в одно нажатие получает тот же пост со своей отслеживаемой ссылкой внутри, на английском или русском. Подробнее: <a href="/ru/partners/market-news">партнёры по рыночным новостям</a>.</li></ul></div>',5)),l(s),e[2]||(e[2]=a('<p>Макро-композит — это контекст, а не сигнал. Поддерживающий фон не повод добирать риск, слабый не повод продавать. TickerForge — образовательное ПО для поддержки решений, не инвестиционная рекомендация.</p><h2 id="смежные-страницы" tabindex="-1">Смежные страницы <a class="header-anchor" href="#смежные-страницы" aria-label="Permalink to &quot;Смежные страницы&quot;">​</a></h2><ul><li><a href="/ru/market-intelligence/">Все чтения Market Intelligence</a></li><li><a href="/blog/economic-health-score">Как мы считаем экономику</a></li><li><a href="/ru/market-intelligence/market-regime">Рыночный режим</a></li><li><a href="/ru/partners/market-news">Партнёрская программа по рыночным новостям</a></li></ul>',3))])}const P=o(h,[["render",d]]);export{T as __pageData,P as default};
